UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Medical Complications Assessment","body":"**Eating disorders affect every organ system.** Identify the primary complication requiring treatment [1][2].\n\n**Cardiovascular:**\n- Bradycardia, hypotension, orthostatic changes\n- QTc prolongation, arrhythmias\n- Pericardial effusion, CHF (refeeding)\n\n**Metabolic/Electrolyte:**\n- Hypokalemia, hypophosphatemia, hypomagnesemia\n- Hypoglycemia\n- Refeeding syndrome (phosphate, K+, Mg2+ drops)\n\n**Hematologic:**\n- Pancytopenia, anemia, leukopenia\n- Bone marrow hypoplasia\n\n**GI:**\n- Gastroparesis, constipation\n- Superior mesenteric artery (SMA) syndrome\n- Mallory-Weiss tears, esophageal rupture\n\n**Endocrine:**\n- Amenorrhea, hypothalamic dysfunction\n- Osteoporosis, stress fractures\n- Sick euthyroid syndrome\n\nWhat is the primary concern?","citation":[1,2],"options":[{"label":"Cardiac Instability","description":"Bradycardia <40, QTc prolongation, syncope","next":"ed-cardiac","urgency":"critical"},{"label":"Electrolyte Derangement","description":"Hypokalemia, hypophosphatemia, hypomagnesemia","next":"ed-electrolytes","urgency":"urgent"},{"label":"Refeeding Syndrome Risk","description":"At risk before feeding, or new electrolyte decline/symptoms after nutrition","next":"ed-refeeding","urgency":"critical"},{"label":"Stable - Proceed to Risk Stratification","description":"No acute medical emergency","next":"ed-risk-strat"}],"summary":"Identify primary complication: cardiac instability, electrolytes, or refeeding syndrome risk"}'::jsonb
